style.css:
/* Solid Barbie-themed background */
body {
    background-color: #ffb6c1; /* Light Barbie pink */
    color: #111;
    font-family: Arial, Helvetica, sans-serif !important; /* Safe, basic font */
}

/* Links */
a {
    color: #ff7f50; /* Summer orange */
    text-decoration: underline;
    transition: all 0.3s;
}

a:hover {
    text-shadow: 0 0 8px #ff7f50;
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    border: none;
    border-radius: 12px;
    padding: 6px 12px;
    cursor: pointer;
    transition: all 0.3s;
    color: #fff;
}

/* Button color cycling by position */
button:nth-of-type(3n+1),
input[type="button"]:nth-of-type(3n+1),
input[type="submit"]:nth-of-type(3n+1) {
    background-color: #ff69b4; /* Barbie pink */
    box-shadow: 0 0 5px #ff69b4;
}

button:nth-of-type(3n+2),
input[type="button"]:nth-of-type(3n+2),
input[type="submit"]:nth-of-type(3n+2) {
    background-color: #7bdff2; /* Malibu blue */
    color: #111;
    box-shadow: 0 0 5px #7bdff2;
}

button:nth-of-type(3n+3),
input[type="button"]:nth-of-type(3n+3),
input[type="submit"]:nth-of-type(3n+3) {
    background-color: #ff7f50; /* Summer orange */
    color: #111;
    box-shadow: 0 0 5px #ff7f50;
}

/* Button hover glow */
button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    transform: scale(1.05);
    box-shadow: 0 0 12px #fff;
}

/* Inputs */
input, textarea, select {
    border-radius: 8px;
    border: 2px solid #ff69b4;
    padding: 4px 8px;
    box-shadow: 0 0 5px #ff69b4;
    transition: all 0.3s;
    font-family: Arial, Helvetica, sans-serif !important;
}

input:focus, textarea:focus, select:focus {
    box-shadow: 0 0 12px #ff7f50;
    border-color: #ff7f50;
}
